draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W / 2, H / 4, 50 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();

  // sorghum
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.rect(W / 2 - 20, H / 2, 40, 100 + 20 * Math.sin(t));
  ctx.fill();

  // stick figure farmer
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W / 2 - 100, H - 100, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 100, H - 80);
  ctx.lineTo(W / 2 - 100, H - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 100, H - 60);
  ctx.lineTo(W / 2 - 80, H - 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 100, H - 60);
  ctx.lineTo(W / 2 - 120, H - 80);
  ctx.stroke();

  ctx.restore();
}
